insert into public.product_faqs (product_id,question_en,question_ar,answer_en,answer_ar,sort_order) values
((select id from public.products where slug='green-tiger-snake-plant'),'What light does this plant need?','ما الإضاءة المناسبة للنبات؟','Low to bright indirect light. Avoid sudden harsh direct sun.','اتبع إرشادات الإضاءة وتجنب تعريض النبات فجأة لشمس مباشرة قوية.',1),
((select id from public.products where slug='green-tiger-snake-plant'),'How should I water it?','إزاي أسقي النبات؟','Allow much of the soil to dry before watering. Do not leave excess water around the inner pot.','افحص التربة قبل الري ولا تترك مياهًا زائدة راكدة حول القصرية الداخلية.',2),
((select id from public.products where slug='green-tiger-snake-plant'),'Why are the leaves turning yellow?','ليه الأوراق بتصفر؟','Yellowing often follows excess water, poor drainage, low light or sudden environmental change.','غالبًا ينتج الاصفرار عن زيادة الري أو ضعف التصريف أو قلة الضوء أو تغير مفاجئ في المكان.',3),
((select id from public.products where slug='green-tiger-snake-plant'),'Will the delivered plant look exactly like the photo?','هل النبات المستلم هيكون مطابق للصورة؟','Natural plants vary slightly in leaf count, colour, shape and exact height.','النباتات الطبيعية تختلف قليلًا في عدد الأوراق واللون والشكل والارتفاع.',4);
